use zopro_bn254::Fr;
#[derive(Clone,Copy,Debug,PartialEq,Eq)]
pub struct Span{pub start:usize,pub width:usize}
pub fn balanced()->[Span;11]{core::array::from_fn(|i|{let start=i*127/11;Span{start,width:(i+1)*127/11-start}})}
pub fn original()->[Span;11]{core::array::from_fn(|i|Span{start:i*12,width:12})}
include!("digit-at.rs");
pub fn digit(s:&[u64;4],high:bool,span:Span)->i16{let i=usize::from(high)*2;let words=[s[i],s[i+1]&0x7fffffffffffffff,0,0];let d=digit_at(&words,span);if s[i+1]>>63!=0{-d}else{d}}
pub fn scalar(s:&[u64;4],high:bool)->i128{let i=usize::from(high)*2;let v=(s[i]as u128)|(((s[i+1]&0x7fffffffffffffff)as u128)<<64);assert!(v<1u128<<126);if s[i+1]>>63!=0{-(v as i128)}else{v as i128}}
pub fn signed_fr(v:i128)->Fr{let f=Fr::from_le_bytes_mod_order(&v.unsigned_abs().to_le_bytes());if v<0{-f}else{f}}
pub fn check(s:&[u64;4]){for spans in[balanced(),original()]{for high in[false,true]{let mut v=0i128;for sp in spans{let d=digit(s,high,sp);assert!(d.unsigned_abs()as usize<=1usize<<(sp.width-1));v=v.checked_add((d as i128).checked_shl(sp.start as u32).unwrap()).unwrap();}assert_eq!(v,scalar(s,high));}if spans==balanced(){for high in[false,true]{assert!(digit(s,high,spans[10]).signum()as i128*scalar(s,high).signum()>=0);}}}}
#[cfg(test)]mod tests{use super::*;
 #[test]fn variable_offset_reconstruction_and_boundaries(){let b=balanced();assert_eq!(b.map(|s|s.width),[11,12,11,12,11,12,11,12,11,12,12]);assert_eq!(b[10].start+b[10].width,127);assert_eq!(b.iter().map(|s|1usize<<(s.width-1)).sum::<usize>(),17408);let mut count=0;let mut values=vec![0u128,1,2,(1u128<<126)-1];for i in 0..126{values.push(1u128<<i);values.push((1u128<<i)-1);if i<125{values.push((1u128<<i)+1);}}let mut seed=0x67656f6d65747279u64;for _ in 0..8192{let mut v=0u128;for i in 0..2{seed^=seed<<13;seed^=seed>>7;seed^=seed<<17;v|=(seed as u128)<<(i*64);}values.push(v&((1u128<<126)-1));}for v in values{for neg in[false,true]{let x=[v as u64,(v>>64)as u64|if neg{1<<63}else{0},v as u64,(v>>64)as u64|if !neg{1<<63}else{0}];check(&x);count+=1;}}assert!(count>16384);}
 #[test]fn variable_weighted_bucket_model_matches_direct_sum(){for n in[0usize,1,7,8,9,199,200,201,513,4097]{for pattern in 0..4{let words=(0..n).map(|i|{let v=match pattern{0=>i as u128,1=>1u128<<125,2=>((i*1597)as u128)<<71,_=>((i*31+7)as u128)<<109};[v as u64,(v>>64)as u64|if i%3==0{1<<63}else{0},(v/3)as u64,((v/3)>>64)as u64]}).collect::<Vec<_>>();let tokens=(0..n).map(|i|Fr::from((i+991)as u64)).collect::<Vec<_>>();for spans in[balanced(),original()]{let mut got=Fr::ZERO;let expected=words.iter().zip(&tokens).map(|(s,p)|(signed_fr(scalar(s,false))+crate::split::phi_lambda()*signed_fr(scalar(s,true)))* *p).fold(Fr::ZERO,|a,b|a+b);for sp in spans{let half=1usize<<(sp.width-1);let size=if sp.width==11{152}else{200};let mut m=crate::model::Model::new(half,size,false);for high in[true,false]{let arrivals=words.iter().zip(&tokens).filter_map(|(s,&p)|{let d=digit(s,high,sp);if d==0{None}else{Some((d.unsigned_abs()as u32-1|if d<0{1<<31}else{0},p))}}).collect::<Vec<_>>();m.feed(&arrivals);if high{m.phi(crate::split::phi_lambda());}}let(b,c)=m.finish();assert!(c.max_batch<=200&&c.max_queue<size);let sum=b.iter().enumerate().map(|(i,p)|Fr::from((i+1)as u64)* *p).fold(Fr::ZERO,|a,b|a+b);got+=sum*Fr::from(2u64).pow(&[sp.start as u64]);}assert_eq!(got,expected);}}}}
}
